option.value:
`Add-Type -AssemblyName System.Drawing
foreach ($n in 1,2,3) {
  $p = "C:\Users\alexa\OpenideProjects\kt2\src\main\resources\cars\$n.png"
  $img = [System.Drawing.Image]::FromFile($p)
  $bmp = New-Object System.Drawing.Bitmap $img
  $minX = $bmp.Width; $minY = $bmp.Height; $maxX = -1; $maxY = -1
  $count = 0
  for ($y=0; $y -lt $bmp.Height; $y+=2) {
    for ($x=0; $x -lt $bmp.Width; $x+=2) {
      $c = $bmp.GetPixel($x,$y)
      if ($c.A -gt 20) {
        $count++
        if ($x -lt $minX) { $minX = $x }
        if ($y -lt $minY) { $minY = $y }
        if ($x -gt $maxX) { $maxX = $x }
        if ($y -gt $maxY) { $maxY = $y }
      }
    }
  }
  Write-Output ("{0}.png bounds=({1},{2})-({3},{4}) size={5}x{6} opaqueApprox={7}" -f $n,$minX,$minY,$maxX,$maxY,($maxX-$minX+1),($maxY-$minY+1),$count)
  $img.Dispose(); $bmp.Dispose()
}
`
